-- Preserve the former inclusive end day; do not reset schedules or task identities.
ALTER TABLE eam_inspection_periodic_plan
 MODIFY COLUMN start_date DATETIME NULL COMMENT 'Plan start time, inclusive, local business time to seconds',
 MODIFY COLUMN end_date DATETIME NULL COMMENT 'Last scheduled inspection time, inclusive, local business time to seconds';
UPDATE eam_inspection_periodic_plan SET end_date=DATE_ADD(end_date,INTERVAL 86399 SECOND)
 WHERE end_date IS NOT NULL;

CREATE OR REPLACE VIEW v_inspection_definition AS SELECT d.id,d.tenant_id,'types' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,NULL type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'period',d.`period_count`,'unit',d.`period_unit`,'sortOrder',d.`sort_order`,'owners',JSON_ARRAY(),'reviewers',JSON_ARRAY(),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',JSON_ARRAY(),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_type d UNION ALL SELECT d.id,d.tenant_id,'standards' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,NULL type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'requirement',d.`requirement`,'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_item r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'equipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_equipment r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.category_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_standard_category r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='display' LIMIT 1),JSON_ARRAY()),'legacyCategoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='legacy' LIMIT 1),JSON_ARRAY()),'details',JSON_ARRAY(),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_standard d UNION ALL SELECT d.id,d.tenant_id,'daily-plans' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,d.type_id type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'typeId',COALESCE(CAST(d.`type_id` AS CHAR),''),'reviewMode',d.`review_mode`,'startDate',COALESCE(DATE_FORMAT(d.`start_date`,'%Y-%m-%d'),''),'endDate',COALESCE(DATE_FORMAT(d.`end_date`,'%Y-%m-%d'),''),'validHours',d.`valid_duration`,'advanceHours',d.`advance_duration`,'remindHours',d.`remind_duration`,'expireRemindHours',d.`expire_remind_duration`,'validUnit',d.`valid_unit`,'advanceUnit',d.`advance_unit`,'remindUnit',d.`remind_unit`,'expireRemindUnit',d.`expire_remind_unit`,'scanMode',d.`scan_mode`,'onlyAbnormal',IF(d.`only_abnormal`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'randomPhotoCount',d.`random_photo_count`,'allowLate',IF(d.`allow_late`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'personMode',d.`person_mode`,'skipUnstaffed',IF(d.`skip_unstaffed`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'restCycle',d.`rest_cycle`,'useShiftEnd',IF(d.`use_shift_end`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',COALESCE((SELECT JSON_ARRAYAGG(r.device_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_daily_plan_device r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'weeklyRestDays',COALESCE((SELECT JSON_ARRAYAGG(r.day_no) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_rest_day r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id AND r.cycle_code='weekly' LIMIT 1),JSON_ARRAY()),'monthlyRestDays',COALESCE((SELECT JSON_ARRAYAGG(r.day_no) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_rest_day r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id AND r.cycle_code='monthly' LIMIT 1),JSON_ARRAY()),'restDays',COALESCE((SELECT JSON_ARRAYAGG(r.day_no) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_rest_day r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'holidays',COALESCE((SELECT JSON_ARRAYAGG(DATE_FORMAT(r.holiday_date,'%Y-%m-%d')) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_holiday r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'shifts',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.shift_key,'name',r.name,'start',TIME_FORMAT(r.start_time,'%H:%i'),'end',TIME_FORMAT(r.end_time,'%H:%i'))) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_shift r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'roster',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('key',r.roster_key,'date',DATE_FORMAT(r.roster_date,'%Y-%m-%d'),'shiftId',r.shift_key,'users',COALESCE((SELECT JSON_ARRAYAGG(CAST(u.user_id AS CHAR)) OVER(ORDER BY u.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_roster_user u WHERE u.tenant_id=r.tenant_id AND u.plan_id=r.plan_id AND u.roster_sort=r.sort_no LIMIT 1),JSON_ARRAY()))) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_daily_roster r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM eam_inspection_daily_plan d UNION ALL SELECT d.id,d.tenant_id,'periodic-plans' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,d.type_id type_id,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'typeId',COALESCE(CAST(d.`type_id` AS CHAR),''),'reviewMode',d.`review_mode`,'startDate',COALESCE(DATE_FORMAT(d.`start_date`,'%Y-%m-%dT%H:%i:%s'),''),'endDate',COALESCE(DATE_FORMAT(d.`end_date`,'%Y-%m-%dT%H:%i:%s'),''),'validHours',d.`valid_duration`,'advanceHours',d.`advance_duration`,'remindHours',d.`remind_duration`,'expireRemindHours',d.`expire_remind_duration`,'validUnit',d.`valid_unit`,'advanceUnit',d.`advance_unit`,'remindUnit',d.`remind_unit`,'expireRemindUnit',d.`expire_remind_unit`,'scanMode',d.`scan_mode`,'onlyAbnormal',IF(d.`only_abnormal`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'randomPhotoCount',d.`random_photo_count`,'allowLate',IF(d.`allow_late`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'period',d.`period_count`,'unit',d.`period_unit`,'nextAt',COALESCE(DATE_FORMAT(d.`next_at`,'%Y-%m-%dT%H:%i:%s'),''),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_periodic_plan_person r WHERE r.tenant_id=d.tenant_id AND r.parent_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'details',COALESCE((SELECT JSON_ARRAYAGG(r.device_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_periodic_plan_device r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id LIMIT 1),JSON_ARRAY()),'restDays',JSON_ARRAY(),'holidays',JSON_ARRAY(),'shifts',JSON_ARRAY(),'roster',JSON_ARRAY()) payload FROM eam_inspection_periodic_plan d;
